// Editorial learning prompts informed by the linked guidance, not a compliance test.
export const ethicsSources={
 oecd:{title:'OECD AI Principles',url:'https://oecd.ai/en/ai-principles',scope:'Fairness, privacy, transparency, safety and accountability.'},
 nist:{title:'NIST AI Risk Management Framework',url:'https://www.nist.gov/itl/ai-risk-management-framework',scope:'A framework for thinking about AI risks and managing them in context.'},
 education:{title:'Department for Education: generative AI in education',url:'https://www.gov.uk/government/publications/generative-artificial-intelligence-in-education/generative-artificial-intelligence-ai-in-education',scope:'England guidance on privacy, intellectual property, assessment and professional judgement. Your institution and local rules may differ. © Crown copyright, Open Government Licence v3.0. These are independent educational prompts, not an official checklist.'},
 copyright:{title:'US Copyright Office: using someone else’s work',url:'https://www.copyright.gov/help/faq/faq-fairuse.html',scope:'US guidance on permissions and exceptions. It does not decide whether your use is lawful or how other countries treat it.'},
 endorsements:{title:'FTC: endorsements and testimonials',url:'https://www.ftc.gov/business-guidance/resources/ftcs-endorsement-guides-what-people-are-asking',scope:'US guidance on honest endorsements and relevant disclosures. Not a worldwide compliance assessment.'}
};
export const ethicsTasks=[
 {id:'hiring',name:'Hiring & CVs',description:'Screen applications or compare candidates.',example:'We want AI to help shortlist job applicants.',cases:['itutorgroup','rite-aid'],caseContext:'iTutorGroup concerns programmed age rules, not proven machine learning. Rite Aid concerns facial recognition, not CV ranking. These cases illustrate screening and review risks; they do not establish how your hiring tool behaves.',questions:[
  {id:'data',title:'What will you share with the tool?',options:[['personal','CVs or other personal details'],['anonymous','Made-up examples or carefully de-identified data'],['unknown','I am not sure what the data includes']]},
  {id:'decision',title:'What will AI do with applications?',options:[['reject','Reject or rank people automatically'],['suggest','Suggest options for a person to review'],['unknown','We have not decided yet']]},
  {id:'criteria',title:'How will you choose the selection criteria?',options:[['tested','Job-related criteria that we plan to test'],['untested','We will use the tool’s default criteria'],['unknown','We have not checked the criteria yet']]}
 ]},
 {id:'studying',name:'Studying & assignments',description:'Learn a topic, draft work or check an answer.',example:'I want AI to help with a college assignment.',cases:['mata'],caseContext:'The court case illustrates unverified AI citations. It does not determine your school’s rules.',questions:[
  {id:'purpose',title:'How do you want AI to help?',options:[['learn','Explain a topic or give practice questions'],['draft','Draft or rewrite part of assessed work'],['submit','Produce work that I will submit as my own']]},
  {id:'rules',title:'Have you checked the assignment’s AI rules?',options:[['allowed','Yes, this use is allowed'],['restricted','There are restrictions or AI use is not allowed'],['unknown','I have not checked yet']]},
  {id:'verify',title:'How will you check the answer?',options:[['check','Use course materials and original sources'],['trust','Rely on the AI answer'],['unknown','I do not have a checking plan yet']]}
 ]},
 {id:'images',name:'Images & creative work',description:'Make a poster, illustration or AI-edited image.',example:'I want to make an AI poster for an event.',cases:['getty-stability-uk','grok-eu-images'],caseContext:'The UK judgment concerns specific intellectual-property claims; the EU record is an investigation into image risks, not a final finding. Neither determines whether your image is lawful.',questions:[
  {id:'reference',title:'What will you use as a reference?',options:[['own','My own work or material with suitable permission'],['other','Someone else’s art, photo or logo'],['unknown','I am unsure where the reference came from']]},
  {id:'person',title:'Will the image show a real person?',options:[['no','No, only fictional people or objects'],['permission','Yes, with permission for this use'],['unclear','Yes, without clear permission']]},
  {id:'sharing',title:'How will people see the result?',options:[['private','Private practice'],['labelled','Public, with its AI role explained'],['unlabelled','Public, without an explanation of AI use']]}
 ]},
 {id:'marketing',name:'Marketing & promotion',description:'Write product copy, adverts or promotional posts.',example:'We want AI to write our product promotion.',cases:['donotpay','workado','rytr'],caseContext:'These records illustrate disputed claims and a changed order. Check each dated outcome.',questions:[
  {id:'claims',title:'What will the content claim?',options:[['description','Basic descriptions we can verify'],['performance','Performance, accuracy or expert-level benefits'],['unknown','We have not checked the claims yet']]},
  {id:'reviews',title:'Will you include reviews or testimonials?',options:[['none','No testimonials'],['real','Real feedback, used with appropriate permission'],['invented','AI-written feedback presented as real customers']]},
  {id:'approval',title:'Who will check the content before publication?',options:[['owner','A named person will check the evidence and wording'],['auto','It will be published automatically'],['unknown','We have not assigned a reviewer']]}
 ]},
 {id:'support',name:'Customer support',description:'Answer questions or help customers resolve issues.',example:'We want a chatbot to answer customer questions.',cases:['ngl','ring'],caseContext:'These cases concern claimed safeguards and privacy failures. They are not evaluations of your chatbot.',questions:[
  {id:'data',title:'What might customers share?',options:[['general','General questions without account details'],['personal','Account details or other personal information'],['unknown','We do not know yet']]},
  {id:'action',title:'What can the assistant do?',options:[['faq','Answer questions from approved information'],['account','Change accounts, refunds or important records'],['unknown','Its permissions have not been set yet']]},
  {id:'handoff',title:'What happens when it cannot help?',options:[['human','A clear route to a person'],['loop','The customer stays with the bot'],['unknown','We have not designed that yet']]}
 ]}
];
export function buildEthicsChecklist(taskId,answers){
 const task=ethicsTasks.find(t=>t.id===taskId);if(!task)throw Error('Choose a supported task.');
 if(!answers||typeof answers!=='object'||Array.isArray(answers))throw Error('Answer all three questions before building the checklist.');
 for(const q of task.questions)if(!q.options.some(([value])=>value===answers[q.id]))throw Error('Answer all three questions before building the checklist.');
 const items=[];
 const add=(title,action,why,source='oecd')=>items.push({title,action,why,source});
 if(taskId==='hiring'){
  add('Plan how someone can question a decision','Keep a record of the criteria and provide a route to a person who can review a disputed outcome.','A hiring decision affects someone’s opportunity. Responsibility should be clear.');
  if(answers.data==='anonymous')add('Keep test data separate from applicant data','If the examples are entirely made up, avoid adding real applicant details. If data came from real people, check whether combinations of details could still identify them.','Invented examples and de-identified records are different; removing a name alone may not remove personal information.');
  else add('Check the data before upload',answers.data==='unknown'?'Identify what the CVs contain before sharing them. Ask your organisation which tools are approved.':'Minimise applicant details. Check the tool’s access, retention and training-use settings and your organisation’s approval process.','Your choice suggests personal data is present or its contents are not yet known.');
  if(answers.decision==='reject')add('Keep an accountable person in the decision','Reconsider automatic rejection. Have a qualified person check consequential decisions and give them the ability to override AI.','You selected automatic ranking or rejection; errors could exclude applicants.');
  else add('Define what the reviewer must check',answers.decision==='unknown'?'Decide whether AI is advising or deciding before selecting a tool.':'Give the reviewer the original application and clear criteria, not just an AI score.','A human review is useful only when the person can assess and change the suggestion.');
  add('Test for unfair screening',answers.criteria==='tested'?'Try varied, realistic applications and examine mistakes and exclusions before and during use.':answers.criteria==='untested'?'Inspect the default criteria. Use criteria that are relevant to the job and test for unfair exclusions rather than assuming defaults are suitable.':'Find out which criteria the tool uses. Agree on job-related criteria and a testing plan before relying on its recommendations.','Criteria that appear convenient can still exclude people unfairly. Testing and review matter even when the criteria sound reasonable.','nist');
 }else if(taskId==='studying'){
  add('Keep private information out','Use invented examples instead of classmates’ details or confidential research material.','An assignment can contain information you do not have permission to share.','education');
  add('Protect the learning goal',answers.purpose==='learn'?'Try the problem yourself, then use AI explanations to check your understanding.':answers.purpose==='draft'?'Keep your own reasoning and be able to explain and defend the submitted work.':answers.rules==='allowed'?'Confirm that permission covers AI-generated submissions, not just assistance. Follow the required acknowledgement and do not hide which parts AI produced.':'Check whether AI-generated submissions are permitted before proceeding. Do not claim unaided authorship for AI-produced work. Keep the work aligned with the assignment’s learning goal.','Learning and allowed assistance depend on the assignment. Permission to use AI does not necessarily cover every kind of submission.','education');
  add('Check what your course allows',answers.rules==='allowed'?'Follow the stated limits and any acknowledgement instructions. Keep a note of how you used AI.':answers.rules==='restricted'?'Stay within the restrictions. If the planned use is disallowed, use a permitted learning method instead.':'Ask your teacher or check the assignment policy before using AI for assessed work.','School and assignment rules differ; this guide cannot grant permission.','education');
  add('Verify facts and references',answers.verify==='check'?'Open the original references and compare the answer with course material.':'Set a checking plan first. Open every citation you intend to rely on and verify claims independently.','AI can produce plausible errors and references that do not exist.','nist');
 }else if(taskId==='images'){
  add('Explain the human contributions','Keep track of reference material, tools, code and creative choices. Credit relevant contributors accurately.','Creative credit is a question of transparency, not just who pressed generate.');
  add('Check reference rights and terms',answers.reference==='own'?'Check rights in the reference and the AI tool’s terms. For licensed material, confirm the licence covers your intended use.':answers.reference==='other'?'Check the source, relevant rights, licence terms and any applicable exceptions. If the basis for use is unclear, seek advice or choose material with clear rights for your purpose.':'Find the reference’s source and relevant terms first, or replace it with material whose rights you can check.','Attribution does not replace a licence where one is needed. Permission is not always required: public-domain material and legal exceptions may apply, depending on context and country.','copyright');
  add('Respect the person in the image',answers.person==='no'?'Check that the result does not unintentionally resemble or impersonate a real person.':answers.person==='permission'?'Confirm the person understands the intended edits, audience and context.':'Get clear permission for the planned use or choose a fictional subject. Avoid misleading impersonation.','A convincing image can affect someone’s privacy or reputation.');
  add('Check the portrayal and audience context',answers.sharing==='private'?'Review the result for harmful stereotypes or misleading portrayals. Revisit rights, consent and audience context before sharing.':answers.sharing==='labelled'?'Make the explanation easy to notice. Review the image and caption for misleading portrayals and harmful stereotypes; a label alone does not remove these concerns.':'Review for harmful stereotypes and explain the AI role where it matters, especially if the image could be mistaken for evidence of a real event.','Private practice and public sharing have different audiences, but neither a private setting nor an AI label resolves every ethical concern.');
 }else if(taskId==='marketing'){
  add('Protect customer information','Use approved information and avoid feeding customer lists or confidential campaign data into an unapproved tool.','Writing promotional copy can expose data as well as produce content.');
  add('Match claims to evidence',answers.claims==='description'?'Check each factual description against current product information.':answers.claims==='performance'?'Gather evidence for each performance or expert-capability claim before publication. Remove claims the evidence cannot support.':'Identify the claims in the draft first, including implied benefits. Then check the evidence for each claim and remove unsupported statements.','Even ordinary product descriptions can mislead if facts, context or limitations are wrong.');
  add('Keep testimonials genuine',answers.reviews==='invented'?'Do not present invented AI feedback as real customer experience. Remove it or replace it with genuine, appropriately authorised feedback.':answers.reviews==='real'?'Preserve the customer’s meaning and check permission and context. Do not invent results while editing. Check whether incentives or other relevant relationships need disclosure.':'Check that AI has not inserted a fake quote, customer story or endorsement.','Readers can be misled by fabricated experience, altered feedback or hidden relevant connections.','endorsements');
  add('Assign publication responsibility',answers.approval==='owner'?'Have the named reviewer check claims, omissions, audience and references.':'Assign a reviewer and an approval step before publishing. Give them the ability to stop or correct the content.','You selected whether someone checks the content before it goes public.','nist');
 }else{
  add('Be clear about the assistant’s role','Explain that customers are using an automated assistant and state what it can and cannot do.','Customers need useful context when deciding whether to rely on an answer.');
  add('Plan for private customer data',answers.data==='general'?'Design the flow to discourage unnecessary account details and handle accidental disclosures.':answers.data==='personal'?'Minimise information collected and check who can access it, how long it stays and whether it is used for training.':'Map the information customers might share before launch. Define what the bot should not request.','Your answer identifies either a data risk or a missing data plan.');
  add('Limit what it can change',answers.action==='faq'?'Keep answers tied to approved information. Test incorrect and out-of-date answers.':answers.action==='account'?'Use narrow permissions, confirmation steps and human review for consequential changes. Keep an audit trail and a correction process.':'Define and test the assistant’s permissions before connecting it to customer systems.','An answer and an action can have very different consequences.','nist');
  add('Make help from a person reachable',answers.handoff==='human'?'Test the handoff and make sure customers can find and use it.':'Add an accessible human route for unresolved or consequential problems. Do not leave customers in a bot loop.','Your answer determines whether to test an existing route or create one.');
 }
 add('Use computing with a purpose','Start with the simplest tool that meets the task. Test quality before choosing a smaller model, and avoid unnecessary repeated generation.','Resource use is one consideration alongside quality, safety and people’s needs. This guide does not measure energy or carbon.');
 return {task,items,answers:task.questions.map(q=>({question:q.title,answer:q.options.find(([v])=>v===answers[q.id])[1]})),reviewedOn:'2026-10-15'};
}
